// ── GCW ERA CSV Parser → ingest-era-data payload ────────────────────────────
// Reads ERA CSV exported from Trizetto portal and maps to EraLineItem[] shape
// expected by the ingest-era-data Supabase edge function.
//
// SETUP REQUIRED:
//   - PRACTICE_ID is hardcoded for GCW below (df52d2fd-...)
//   - GCW_NPI is hardcoded below (1831993245)
//   - Column mappings in Section 4 handle common Trizetto header variations.
//     If columns don't resolve, add the actual header name to the candidates list.
// ─────────────────────────────────────────────────────────────────────────────

const PRACTICE_ID = 'df52d2fd-5e88-48de-9c45-13d0ae7847b0'; // GCW practice UUID
const GCW_NPI     = '1831993245';                              // Dr. Greatwood / GCW NPI

// ── 1. Read binary data from Google Drive download ───────────────────────────
const item     = $input.first();
const fileName = item.json?.name || 'era_unknown.csv';

// Find the binary key (Google Drive download node uses 'data' by default)
const binaryKey = Object.keys(item.binary || {})[0];
if (!binaryKey) {
  throw new Error(`[gcw-era-watcher] No binary data found for file: ${fileName}`);
}
const b64 = item.binary[binaryKey].data;
const fileText = Buffer.from(b64, 'base64').toString('utf8');

// ── 2. Detect file format ─────────────────────────────────────────────────────
// 835 EDI files begin with 'ISA' segment. CSV files begin with a header row.
if (fileText.trimStart().startsWith('ISA')) {
  console.warn(`[gcw-era-watcher] 835 EDI format detected in ${fileName} — not yet supported. Ask biller to export CSV instead.`);
  return [{
    json: {
      practice_id: PRACTICE_ID,
      items: [],
      batch_id: `gcw-era-skipped-${fileName}`,
      skipped: true,
      reason: '835_EDI_not_yet_supported'
    }
  }];
}

// ── 3. CSV parser (RFC 4180 compliant, handles quoted fields) ─────────────────
function parseCSV(text) {
  const lines = text.split(/\r?\n/).filter(l => l.trim().length > 0);
  if (lines.length < 2) throw new Error('[gcw-era-watcher] CSV has fewer than 2 lines (no data rows)');

  function parseRow(line) {
    const fields = [];
    let field = '', inQuote = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') {
        if (inQuote && line[i + 1] === '"') { field += '"'; i++; }
        else inQuote = !inQuote;
      } else if (ch === ',' && !inQuote) {
        fields.push(field.trim());
        field = '';
      } else {
        field += ch;
      }
    }
    fields.push(field.trim());
    return fields;
  }

  const rawHeaders = parseRow(lines[0]);
  // Normalize headers: lowercase, spaces→underscores, strip non-alphanumeric
  const headers = rawHeaders.map(h =>
    h.toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '')
  );

  const rows = lines.slice(1).map(line => {
    const values = parseRow(line);
    return Object.fromEntries(headers.map((h, i) => [h, values[i] ?? '']));
  });

  return { headers, rows };
}

const { headers, rows } = parseCSV(fileText);
console.info(`[gcw-era-watcher] Parsed ${rows.length} data rows from ${fileName}. Headers: ${headers.join(', ')}`);

// ── 4. Column resolver ────────────────────────────────────────────────────────
// Tries multiple normalized header variations for each logical field.
// If a column is missing, the value will be '' (empty string).
// Add Trizetto-specific header names as additional candidates if needed.
function col(row, ...candidates) {
  for (const c of candidates) {
    const key = c.toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '');
    if (row[key] !== undefined && row[key] !== '') return row[key];
  }
  return '';
}

function money(val) {
  if (val === '' || val === null || val === undefined) return 0;
  return parseFloat(String(val).replace(/[$,()]/g, '')) || 0;
}

function deriveStatus(paid, allowed) {
  if (!allowed || allowed === 0) return 'denied';
  if (paid >= allowed * 0.99) return 'paid';
  if (paid > 0) return 'partial';
  return 'denied';
}

// ── 5. Map rows to EraLineItem[] ──────────────────────────────────────────────
const batchDate = new Date().toISOString().slice(0, 10);
const items = [];
let skippedRows = 0;

for (const row of rows) {
  // Required dedup fields — rows missing any of these are skipped
  const payerId     = col(row, 'payer_id', 'payer id', 'payerid', 'payer_code', 'insurance_id');
  const claimNumber = col(row, 'claim_number', 'claim number', 'claimnumber', 'patient_control_number', 'pcn', 'claim_ref');
  const cptCode     = col(row, 'cpt_code', 'cpt', 'procedure_code', 'service_code', 'proc_code', 'hcpcs');
  const dos         = col(row, 'date_of_service', 'dos', 'service_date', 'from_date', 'service_from');

  if (!payerId || !claimNumber || !cptCode || !dos) {
    skippedRows++;
    if (skippedRows <= 3) {
      console.warn(`[gcw-era-watcher] Skipping row — missing dedup field(s): payer_id='${payerId}' claim='${claimNumber}' cpt='${cptCode}' dos='${dos}'`);
    }
    continue;
  }

  const billed   = money(col(row, 'billed_amount', 'charge_amount', 'submitted_amount', 'billed', 'charges'));
  const allowed  = money(col(row, 'allowed_amount', 'approved_amount', 'allowed', 'contract_amount'));
  const paid     = money(col(row, 'paid_amount', 'payment_amount', 'paid', 'check_amount', 'net_payment'));
  const patResp  = money(col(row, 'patient_responsibility', 'patient_resp', 'patient_amount', 'copay', 'deductible'));
  const adj      = parseFloat((billed - allowed).toFixed(2));

  const checkDate   = col(row, 'check_date', 'payment_date', 'eft_date', 'settlement_date', 'check_issue_date');
  const checkNumber = col(row, 'check_number', 'check_num', 'eft_number', 'trace_number', 'payment_ref');
  const remarkCode  = col(row, 'remark_code', 'adjustment_reason_code', 'carc', 'reason_code', 'denial_code');
  const remarkDesc  = col(row, 'remark_description', 'adjustment_reason', 'denial_reason', 'reason_description');
  const payerName   = col(row, 'payer_name', 'payer', 'insurance_company', 'insurance_name');
  const patientName = col(row, 'patient_name', 'patient', 'member_name', 'beneficiary');
  const memberId    = col(row, 'member_id', 'member_number', 'subscriber_id', 'insurance_id', 'member');

  items.push({
    // Required dedup key fields
    payer_id:               payerId,
    claim_number:           claimNumber,
    cpt_code:               cptCode,
    date_of_service:        dos,

    // Financials
    billed_amount:          billed,
    allowed_amount:         allowed,
    paid_amount:            paid,
    adjustment_amount:      adj,
    patient_responsibility: patResp,

    // Claim metadata
    payer_name:             payerName,
    patient_name:           patientName,
    patient_account:        memberId,
    npi:                    GCW_NPI,
    claim_status:           deriveStatus(paid, allowed),
    remark_code:            remarkCode,
    adjustment_reason:      remarkDesc,
    check_number:           checkNumber,
    check_date:             checkDate || batchDate,
    era_transaction_date:   checkDate || batchDate,

    // Pipeline metadata
    practice_id: PRACTICE_ID,
    source_type: 'trizetto_era'
  });
}

if (skippedRows > 3) {
  console.warn(`[gcw-era-watcher] ...and ${skippedRows - 3} more rows skipped (missing dedup fields). Check column mappings.`);
}

console.info(`[gcw-era-watcher] Mapped ${items.length} line items from ${rows.length} rows. Skipped: ${skippedRows}. File: ${fileName}`);

const batchId = `gcw-era-${fileName.replace(/[^a-z0-9.\-_]/gi, '_')}-${batchDate}`;
return [{ json: { practice_id: PRACTICE_ID, items, batch_id: batchId } }];

// Success path — log summary and pass through
const r = $input.first().json;
console.info(`[gcw-era-watcher] SUCCESS — processed: ${r.records_processed}, inserted: ${r.records_inserted}, skipped: ${r.records_skipped}, bq_errors: ${r.bq_errors}`);
return [{ json: { status: 'ok', ...r } }];
